package io.github.jesterportfolio.hearth.survival;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;import java.util.concurrent.atomic.AtomicLong;
import io.github.jesterportfolio.hearth.survival.rpg.*;
import io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.Role;
import io.github.jesterportfolio.hearth.economy.RpgStore;
class RpgPolicyTest {
    static Properties defaults()throws Exception{var p=new Properties();try(var in=RpgPolicyTest.class.getResourceAsStream("/rpg-policy.properties")){p.load(in);}return p;}
    static RpgPolicy policy(String unit,String scopes)throws Exception{var p=defaults();p.setProperty("drop-unit",unit);p.setProperty("xp-scope","both_progress");p.setProperty("xp-rounding","floor");p.setProperty("charm.scopes",scopes);return RpgPolicy.parse(p);}
    @Test void allRolesAndUnsettledPoliciesAreExplicit()throws Exception{var p=RpgPolicy.parse(defaults());assertFalse(p.ready(Role.PUBLIC_HOME));assertFalse(p.ready(Role.RESOURCE));assertFalse(p.ready(Role.END));assertTrue(p.ready(Role.PRIVATE_HOME));assertTrue(p.ready(Role.NOVICE_RESOURCE));assertEquals(.05,p.deaths().get(Role.NETHER).dropRate());assertEquals(.30,p.deaths().get(Role.END).dropRate());assertTrue(policy("item","none").ready(Role.RESOURCE));}
    @Test void exactSlotConservationAndMetadataIdentity()throws Exception{var p=policy("item","none");var slots=List.of(new RpgPolicy.Slot(0,"metaA",64,.5,false),new RpgPolicy.Slot(1,"metaB",7,1,false));var out=p.split(slots,false,new Random(11));assertEquals(64,out.kept().getOrDefault(0,0)+out.dropped().getOrDefault(0,0));assertEquals(7,out.dropped().get(1));assertTrue(out.dropped().get(0)>0&&out.dropped().get(0)<64);assertThrows(IllegalArgumentException.class,()->p.split(List.of(slots.get(0),slots.get(0)),false,new Random()));}
    @Test void stackIsAllOrNothingAndZeroNeverDrops()throws Exception{var p=policy("stack","none");for(int i=0;i<40;i++){var out=p.split(List.of(new RpgPolicy.Slot(0,"a",64,.5,false),new RpgPolicy.Slot(1,"b",64,0,false)),false,new Random(i));assertTrue(Set.of(0,64).contains(out.dropped().getOrDefault(0,0)));assertEquals(64,out.kept().get(1));}}
    @Test void exactlyOneCharmConsumesOneItemAndOnlyChosenScopes()throws Exception{var slots=List.of(new RpgPolicy.Slot(0,"charm",3,1,true),new RpgPolicy.Slot(1,"sword",1,1,false),new RpgPolicy.Slot(2,"charm",2,1,true));var all=policy("item","items,vanilla_xp,aura_xp").split(slots,true,new Random());assertEquals(0,all.charmSlot());assertEquals(Map.of(0,2,1,1,2,2),all.kept());assertTrue(all.dropped().isEmpty());var xpOnly=policy("item","vanilla_xp").split(slots,true,new Random());assertEquals(2,xpOnly.dropped().get(0));var none=policy("item","none").split(slots,true,new Random());assertNull(none.charmSlot());assertEquals(3,none.dropped().get(0));}
    @Test void safeWorldsNeverConsumeCharmForAbsentPenalties()throws Exception{var p=policy("item","items,vanilla_xp,aura_xp");var zero=List.of(new RpgPolicy.Slot(0,"charm",1,0,true));assertFalse(p.needsCharm(zero,p.deaths().get(Role.PRIVATE_HOME)));assertFalse(p.needsCharm(zero,p.deaths().get(Role.NOVICE_RESOURCE)));assertTrue(p.needsCharm(zero,p.deaths().get(Role.RESOURCE)));assertTrue(p.needsCharm(zero,p.deaths().get(Role.END)));}
    @Test void probabilityBoundaryIsStrictAndRewardCapacityFailsClosed()throws Exception{var p=policy("item","none");var out=p.split(List.of(new RpgPolicy.Slot(0,"a",64,.05,false)),false,new Random(){public double nextDouble(){return .05;}});assertEquals(64,out.kept().get(0));var c=new RewardCoordinator(()->0,new Random(5));for(int i=0;i<8192;i++)c.begin(new UUID(0,i),true);assertThrows(IllegalStateException.class,()->c.begin(new UUID(1,0),true));}
    @Test void thirdRoundingAndVanillaCurve()throws Exception{var p=policy("item","none");assertEquals(3,p.remainingThird(4));assertEquals(2,p.remainingThird(3));for(int level:new int[]{0,1,15,16,17,30,31,32,40,100,1000}){assertEquals(level,VanillaXp.decode(VanillaXp.at(level)).level());assertEquals(VanillaXp.next(level),VanillaXp.at(level+1)-VanillaXp.at(level));}var props=defaults();props.setProperty("xp-rounding","ceil");assertEquals(2,RpgPolicy.parse(props).remainingThird(4));}
    @Test void rewardRollAndDeliveryAreOncePerActionNotPerPlugin(){var now=new AtomicLong();var c=new RewardCoordinator(now::get,new Random(7));UUID id=UUID.randomUUID();var first=c.begin(id,true);assertSame(first,c.begin(id,false));assertEquals(.5,first.skillFactor());var delivered=new ArrayList<List<String>>();assertTrue(c.deliver(id,"fortune-final",List.of("diamond"),delivered::add));assertFalse(c.deliver(id,"fortune-final",List.of("diamond"),delivered::add));assertEquals(1,delivered.size());assertEquals(first.suppressItems()?List.of():List.of("diamond"),delivered.getFirst());assertTrue(c.deliver(id,"custom-enchant",List.of("bonus"),delivered::add));now.set(10001);assertFalse(c.deliver(id,"late",List.of("late"),delivered::add));c.expire();assertFalse(c.claim(id,"again"));}
    @Test void visitorCombatPermissionNeverGrantsBuildOrEntityDamage(){assertTrue(io.github.jesterportfolio.hearth.survival.housing.HousingState.canDamage(false,true,true));assertFalse(io.github.jesterportfolio.hearth.survival.housing.HousingState.canDamage(false,true,false));assertFalse(io.github.jesterportfolio.hearth.survival.housing.HousingState.canDamage(false,false,true));}
    @Test void permissionsSeparateOwnerListAndPublic(){UUID owner=UUID.randomUUID(),friend=UUID.randomUUID(),other=UUID.randomUUID(),w=UUID.randomUUID();var a=new RpgStore.Acl(UUID.randomUUID(),owner,w,0,64,0,1,64,0,RpgStore.Mode.LIST,Set.of(friend),0);assertTrue(a.permits(owner));assertTrue(a.permits(friend));assertFalse(a.permits(other));assertTrue(a.contains(w,1,64,0));assertThrows(IllegalArgumentException.class,()->new RpgStore.Acl(UUID.randomUUID(),owner,w,Integer.MAX_VALUE,64,0,Integer.MAX_VALUE,64,0,RpgStore.Mode.PUBLIC,Set.of(),0));assertFalse(a.contains(UUID.randomUUID(),1,64,0));assertThrows(IllegalArgumentException.class,()->new RpgStore.Home(owner,w,Double.NaN,64,0,0,0,0));}
}
